import { useEffect, useState } from "react";

const API_BASE = "http://localhost:5000/api";
const API_STUDENTS = `${API_BASE}/students`;
const API_COURSES = `${API_BASE}/courses`;
const API_REGISTRATIONS = `${API_BASE}/registrations`;

export default function Registrations() {
  const [students, setStudents] = useState([]);
  const [courses, setCourses] = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [form, setForm] = useState({ 
    studentId: "", 
    courseId: "", 
    semester: "" 
  });
  
  const [isLoading, setIsLoading] = useState({
    students: true,
    courses: true,
    registrations: true
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  // Fetch all data on component mount
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch students
        const studentsRes = await fetch(API_STUDENTS);
        if (!studentsRes.ok) throw new Error('Failed to fetch students');
        const studentsData = await studentsRes.json();
        setStudents(Array.isArray(studentsData) ? studentsData : []);
        
        // Fetch courses
        const coursesRes = await fetch(API_COURSES);
        if (!coursesRes.ok) throw new Error('Failed to fetch courses');
        const coursesData = await coursesRes.json();
        setCourses(Array.isArray(coursesData) ? coursesData : []);
        
        // Fetch registrations
        const registrationsRes = await fetch(API_REGISTRATIONS);
        if (!registrationsRes.ok) throw new Error('Failed to fetch registrations');
        const registrationsData = await registrationsRes.json();
        
        // Debug logs
        console.log('Raw registrations data:', registrationsData);
        if (registrationsData.length > 0) {
          console.log('First registration student data:', registrationsData[0].student);
          console.log('Available student fields:', Object.keys(registrationsData[0].student || {}));
        }
        
        setRegistrations(Array.isArray(registrationsData) ? registrationsData : []);
        
      } catch (err) {
        setError(err.message);
      } finally {
        setIsLoading({ students: false, courses: false, registrations: false });
      }
    };

    fetchData();
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    // Clear any previous errors when user starts typing
    if (error) setError("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    
    // Validate form
    if (!form.studentId || !form.courseId || !form.semester.trim()) {
      setError("Please fill in all fields");
      return;
    }

    try {
      const response = await fetch(API_REGISTRATIONS, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json" 
        },
        body: JSON.stringify({
          studentId: form.studentId,
          courseId: form.courseId,
          semester: form.semester.trim()
        }),
      });

      const data = await response.json();
      
      if (!response.ok) {
        throw new Error(data.message || "Failed to register student");
      }

      // Add new registration to the list
      setRegistrations([...registrations, data]);
      
      // Reset form
      setForm({ studentId: "", courseId: "", semester: "" });
      setSuccess("Student registered successfully!");
      
    } catch (err) {
      setError(err.message || "An error occurred while processing your request.");
    }
  };

  // Show loading state
  if (isLoading.students || isLoading.courses || isLoading.registrations) {
    return (
      <div className="container mt-5 text-center">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
        <p className="mt-2">Loading data...</p>
      </div>
    );
  }

  return (
    <div className="container mt-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Course Registrations</h2>
      </div>

      {/* Success and Error Messages */}
      {error && (
        <div className="alert alert-danger alert-dismissible fade show" role="alert">
          {error}
          <button 
            type="button" 
            className="btn-close" 
            onClick={() => setError("")}
            aria-label="Close"
          ></button>
        </div>
      )}
      
      {success && (
        <div className="alert alert-success alert-dismissible fade show" role="alert">
          {success}
          <button 
            type="button" 
            className="btn-close" 
            onClick={() => setSuccess("")}
            aria-label="Close"
          ></button>
        </div>
      )}

      {/* Registration Form */}
      <div className="card mb-4">
        <div className="card-header bg-primary text-white">
          <h5 className="mb-0">Register Student for Course</h5>
        </div>
        <div className="card-body">
          <form onSubmit={handleSubmit}>
            <div className="row g-3">
              <div className="col-md-4">
                <label htmlFor="studentId" className="form-label">Student</label>
                <select
                  id="studentId"
                  className="form-select"
                  name="studentId"
                  value={form.studentId}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select Student</option>
                  {students.map((student) => (
                    <option key={student._id} value={student._id}>
                      {student.name} ({student.studentId || 'N/A'})
                    </option>
                  ))}
                </select>
              </div>

              <div className="col-md-4">
                <label htmlFor="courseId" className="form-label">Course</label>
                <select
                  id="courseId"
                  className="form-select"
                  name="courseId"
                  value={form.courseId}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select Course</option>
                  {courses.map((course) => (
                    <option key={course._id} value={course._id}>
                      {course.code} - {course.name}
                    </option>
                  ))}
                </select>
              </div>

              <div className="col-md-2">
                <label htmlFor="semester" className="form-label">Semester/Year</label>
                <input
                  type="text"
                  id="semester"
                  className="form-control"
                  name="semester"
                  placeholder="e.g., 2023/1"
                  value={form.semester}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="col-md-2 d-flex align-items-end">
                <button 
                  type="submit" 
                  className="btn btn-primary w-100"
                  disabled={!form.studentId || !form.courseId || !form.semester.trim()}
                >
                  Register
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>

      {/* Registrations Table */}
      <div className="card">
        <div className="card-header bg-light">
          <h5 className="mb-0">Current Registrations</h5>
        </div>
        <div className="card-body p-0">
          {registrations.length === 0 ? (
            <div className="text-center p-4 text-muted">
              <p className="mb-0">No registrations found. Register a student to get started.</p>
            </div>
          ) : (
            <div className="table-responsive">
              <table className="table table-hover mb-0">
                <thead className="table-light">
                  <tr>
                    <th>#</th>
                    <th>Student</th>
                    <th>Course</th>
                    <th>Semester/Year</th>
                    <th>Date Registered</th>
                  </tr>
                </thead>
                <tbody>
                  {registrations.map((registration, index) => (
                    <tr key={registration._id}>
                      <td>{index + 1}</td>
                      <td>
                        <div className="d-flex flex-column">
                          <span className="fw-semibold">{registration.student?.name || 'N/A'}</span>
                          <div className="d-flex align-items-center gap-2">
                            <span className="badge bg-secondary">
                              studentId: {registration.student?.studentId || 'N/A'}
                            </span>
                            {registration.student?.email && (
                              <small className="text-muted">
                                {registration.student.email}
                                
                              </small>
                            )}
                          </div>
                        </div>
                      </td>
                      <td>
                        <div className="fw-semibold">{registration.course?.code || 'N/A'}</div>
                        <small className="text-muted">{registration.course?.name || ''}</small>
                      </td>
                      <td>{registration.semester || 'N/A'}</td>
                      <td>
                        {new Date(registration.createdAt).toLocaleDateString()}
                        <div className="text-muted small">
                          {new Date(registration.createdAt).toLocaleTimeString()}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
